1	using Guardrails.Core.Graph;
2	
3	namespace Guardrails.Core.Tests;
4	
5	/// <summary>
6	/// Unit tests for <see cref="HtmlDiagramRenderer.Render"/> (issue #33): the self-contained local
7	/// <c>diagram.html</c> viewer. Pure string mapping — no disk. Pins the provenance line, the
8	/// verbatim-source embedding, the interaction prerequisites (loose security for clicks, pan/zoom,
9	/// fullscreen), determinism, and newline normalization.
10	/// </summary>
11	public sealed class HtmlDiagramRendererTests
12	{
13	    private const string Hash = "abc123def456";
14	    private const string Source = "flowchart TD\n  task_a[\"a\"]:::task\n  classDef task fill:#cfe8ff;";
15	
16	    private static readonly IReadOnlyDictionary<string, string> NoTargets =
17	        new Dictionary<string, string>(StringComparer.Ordinal);
18	
19	    private static readonly IReadOnlyDictionary<string, string> OneTarget =
20	        new Dictionary<string, string>(StringComparer.Ordinal) { ["task_01_a"] = "tasks/01-a/" };
21	
22	    [Fact]
23	    public void Render_FirstLine_IsProvenanceComment_WithSameHash()
24	    {
25	        string html = HtmlDiagramRenderer.Render(Source, Hash, NoTargets);
26	        string firstLine = html.Split('\n')[0];
27	
28	        // Same provenance shape as diagram.md, and FIRST so the \A-anchored reader (graph --check)
29	        // matches it in both files.
30	        Assert.Equal($"<!-- guardrails:graph v1 source-sha256={Hash} -->", firstLine);
31	    }
32	
33	    [Fact]
34	    public void Render_EmbedsSourceVerbatim_InRawTextScript()
35	    {
36	        string html = HtmlDiagramRenderer.Render(Source, Hash, NoTargets);
37	
38	        Assert.Contains("type=\"text/plain\"", html);
39	        Assert.Contains(Source, html); // verbatim — not interpolated into a JS string
40	        Assert.Contains("<!doctype html>", html);
41	    }
42	
43	    [Fact]
44	    public void Render_EnablesClicksAndNavigation()
45	    {
46	        string html = HtmlDiagramRenderer.Render(Source, Hash, NoTargets);
47	
48	        // Clicks (node -> source file) only fire when mermaid runs in 'loose' security.
49	        Assert.Contains("securityLevel: 'loose'", html);
50	        // Pan/zoom + fullscreen affordances.
51	        Assert.Contains("svg-pan-zoom", html);
52	        Assert.Contains("requestFullscreen", html);
53	    }
54	
55	    [Fact]
56	    public void Render_RaisesMermaidSizeCeilings_SoLargeDagsRender()
