        // The FINAL settled render (wired at run-end by 06-wire-diagramobserver-into-runcommand,
        // mirroring LogSiteRenderer.ExportSite's includeRefresh:false): each node still shows its
        // final settled status badge, but the durable file must NOT keep reloading — so the overlay is
        // present while the meta-refresh tag is absent. The two are INDEPENDENT.
        string html =
            HtmlDiagramRenderer.Render(Source, Hash, OneTarget, SampleStatuses, includeRefresh: false);

        Assert.DoesNotContain("<meta http-equiv=\"refresh\"", html, StringComparison.Ordinal);

        // The status overlay is still emitted: "plan_guardrails" QUOTED is a status-map key present in
        // SampleStatuses but not OneTarget, so it proves the overlay ran even with refresh suppressed.
        // (Quoted deliberately — the bare word also occurs in a template code-comment.)
        Assert.Contains("\"plan_guardrails\"", html, StringComparison.Ordinal);
    }

    [Fact]
    public void Render_WithNodeStatuses_EmitsAnOverlayForEachStatusEntry()
    {
        // Every node in the status map must be reachable by the overlay-rendering logic. Mirror the
        // existing task-folder-targets JSON side-table pattern (Render_EmbedsTaskFolderTargets...): the
        // id appears as a quoted key in the embedded status map the overlay script reads back. Quoting
        // makes the check exact — "task_01_a" is not satisfied by "task_01_a_pf_0" alone.
        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, SampleStatuses);

        foreach (string nodeId in SampleStatuses.Keys)
        {
            Assert.Contains($"\"{nodeId}\"", html, StringComparison.Ordinal);
        }
    }

    [Fact]
    public void Render_WithRunningStatus_EmitsASpinnerClass_AndSettledStatusesEmitAGlyph()
    {
        var statuses = new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["task_01_a"] = "running",
            ["task_01_b"] = "passed",
            ["task_01_c"] = "failed",
        };
        string html = HtmlDiagramRenderer.Render(Source, Hash, OneTarget, statuses);

        // A "running" node renders an ANIMATED spinner via a CSS @keyframes rotation (the task
        // mandates this technique and forbids an external image/GIF) — @keyframes + an animation
        // property are the structural signature of the spinner, distinct from a settled node's static
        // check/X/"?" glyph, which does not animate.
        Assert.Contains("@keyframes", html, StringComparison.Ordinal);
        Assert.Contains("animation", html, StringComparison.Ordinal);

        // The status vocabulary drives the per-node representation (running -> spinner, settled ->
        // glyph); each word reaches the overlay logic (in the embedded status map at minimum).
        Assert.Contains("running", html, StringComparison.Ordinal);
        Assert.Contains("passed", html, StringComparison.Ordinal);
        Assert.Contains("failed", html, StringComparison.Ordinal);
    }
}

/// </remarks>
public static string Render(
    string mermaidSource, string sourceHash, IReadOnlyDictionary<string, string> taskFolderTargets,
    IReadOnlyDictionary<string, string>? nodeStatuses = null, bool includeRefresh = true)
{
    ArgumentNullException.ThrowIfNull(mermaidSource);
    ArgumentException.ThrowIfNullOrEmpty(sourceHash);
    ArgumentNullException.ThrowIfNull(taskFolderTargets);

    // Live status overlay (issue #219) — TDD STUB. When a per-node status map is supplied the
    // during-run / final diagram additionally carries a corner-anchored status badge per node
    // (spinner while running, settled glyph once finished) and — gated on includeRefresh — a
    // <meta http-equiv="refresh"> so a file:// view re-reads itself as the run progresses. That
    // rendering is deliberately NOT implemented here: this task (01-author-tests-...) only
    // authors the failing tests; 02-implement-diagram-status-overlay-renderer turns them green.
    // Throwing (rather than silently emitting nothing) keeps the RED honest and guarantees the
    // null path below stays byte-identical to today for the static `graph` command and every
    // golden fixture — includeRefresh has no effect while nodeStatuses is null, by construction.
    if (nodeStatuses is not null)
    {
        _ = includeRefresh; // meaningful only alongside nodeStatuses — wired by task 02.
        throw new NotImplementedException(
            "Live per-node status overlay rendering (nodeStatuses) is not implemented yet — see " +
            "task 02-implement-diagram-status-overlay-renderer (issue #219). Call Render without " +
            "nodeStatuses for the static graph.");
    }

    // Newline-normalize so the file is byte-identical across OSes (mirrors the renderer/hash).
    string source = mermaidSource
        .Replace("\r\n", "\n", StringComparison.Ordinal)
        .Replace("\r", "\n", StringComparison.Ordinal)
        .TrimEnd('\n');

    // Encoder that escapes NOTHING beyond what JSON strictly requires (default System.Text.Json
    // escapes '<', '>', '&', etc. as \uXXXX for HTML safety, which is unnecessary here — the
    // JSON sits inside a <script type="application/json"> element, read back via textContent,
    // exactly like the Mermaid source above — but using the unsafe-relaxed encoder keeps a
    // task-id containing e.g. "&" readable in the raw HTML source without changing behavior).
    string targetsJson = JsonSerializer.Serialize(taskFolderTargets, new JsonSerializerOptions
    {
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    });

    // Normalize the full output — the template raw-string literal picks up \r\n when the
    // file is checked out with CRLF on Windows; the mermaid source is already normalized above.
